<?php ini_set('display_errors', 0); error_reporting(0);
header("Access-Control-Allow-Origin: *"); header("Content-Type: application/json; charset=UTF-8"); header("Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS"); header("Access-Control-Allow-Headers: Content-Type, Access-Control-Allow-Headers, Authorization, X-Requested-With");
if ($_SERVER['REQUEST_METHOD'] == 'OPTIONS') { http_response_code(200); exit(); }
$host = "localhost"; $db_name = "stockmanager"; $username = "root"; $password = ""; // No WampServer a senha padrão costuma ser vazia
try { $conn = new PDO("mysql:host=" . $host . ";dbname=" . $db_name . ";charset=utf8mb4", $username, $password); $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION); $conn->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC); } catch (PDOException $exception) { http_response_code(200); echo json_encode([ "success" => false, "message" => "Erro na conexão com o banco de dados: " . $exception->getMessage() ]); exit(); }